import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        T = int(t_str)
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            S = next(iterator)
        except StopIteration:
            break

        count_ones = S.count('1')

        if count_ones % 2 == 1:
            results.append("WIN")
        else:
            results.append("LOSE")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
